import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement
  if (config.position) {
    group.position.set(config.position[0], config.position[1], config.position[2]);
  }
  if (config.rotation) {
    group.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
  }
  if (config.scale) {
    group.scale.set(config.scale[0], config.scale[1], config.scale[2]);
  }

  // Load sprite texture
  const spriteTexture = ctx.textureLoader.load(config.imageUrl);
  spriteTexture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry (512x320 atlas region → 1.6:1 aspect ratio)
  const spriteGeometry = new THREE.PlaneGeometry(1.6, 1);

  // Material with TSL texture node
  const texNode = textureNode(spriteTexture);
  const spriteMaterial = new THREE.MeshBasicNodeMaterial({
    colorNode: texNode,
    transparent: true,
  });

  // Sprite mesh
  const spriteMesh = new THREE.Mesh(spriteGeometry, spriteMaterial);
  group.add(spriteMesh);

  // Render text from font atlas
  if (config.textContent) {
    let textStr = config.textContent;

    // Normalize text content format
    if (Array.isArray(textStr) && textStr.length > 0) {
      textStr = textStr[0];
    }
    if (typeof textStr === 'object' && textStr !== null) {
      textStr = textStr.text || '';
    }

    if (typeof textStr === 'string' && textStr.length > 0) {
      const textMesh = ctx.fontAtlas.createText(textStr, {
        font: 'display',
        size: 0.34,
        weight: 400,
        color: config.colors?.ink || '#16161d',
        alignment: 'center',
      });

      if (textMesh) {
        textMesh.position.z = 0.05;
        group.add(textMesh);
      }
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    spriteGeometry.dispose();
    spriteMaterial.dispose();
    spriteTexture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
